mapper.select:
SELECT ni.id, ni.module, ni.node_key AS nodeKey, ni.disabled, cnm.type, cnm.type_name AS typeName, ni.create_user_name AS createUserName, ni.create_time AS createTime, ni.update_user_name AS updateUserName, ni.update_time AS updateTime, dn.node_name AS nodeName FROM notice_info ni INNER JOIN cfg_node_member cnm ON cnm.node_key=ni.node_key AND cnm.is_deleted=FALSE LEFT JOIN dict_node dn ON dn.node_key=ni.node_key WHERE ni.is_deleted=False
AND ni.module=#{params.module}
AND dn.node_name ilike concat('%',#{params.nodeName}::text,'%')
ORDER BY
${item.field} ${item.sort}
ni.create_time DESC
